# Cache zone definition
proxy_cache_path /var/cache/nginx/apicache levels=1:2 keys_zone=apicache:10m max_size=100m inactive=60m;

server {
    listen 80;
    server_name localhost;

    # API service endpoints with caching
    location /api/service1 {
        proxy_pass http://localhost:3000/data;
